def find_hollow_rects(grid):
    """Find all rectangular regions where border is solid color and interior is different"""
    rects = []
    colors = sorted(set(c for row in grid for c in row))
    for color in colors:
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if grid[i][j] == color:
                    height = 1
                    while i+height < len(grid) and grid[i+height][j] == color:
                        height += 1
                    width = 1
                    while j+width < len(grid[0]) and grid[i][j+width] == color:
                        width += 1

                    if height >= 3 and width >= 3:
                        border_ok = True
                        for h in range(height):
                            if grid[i+h][j] != color or grid[i+h][j+width-1] != color:
                                border_ok = False
                        for w in range(1, width-1):
                            if grid[i][j+w] != color or grid[i+height-1][j+w] != color:
                                border_ok = False

                        if border_ok:
                            interior = []
                            for h in range(1, height-1):
                                for w in range(1, width-1):
                                    interior.append(((i+h, j+w), grid[i+h][j+w]))

                            if interior:
                                rects.append((color, i, j, i+height-1, j+width-1, interior))
    return rects

