# Let me identify the PRIMARY hollow frames (non-overlapping, well-defined)
test_lines = test_input_str.strip().split('\n')
test_in = [[int(x) for x in line.split()] for line in test_lines]

# Simple approach: find rectangular regions where all border pixels are same color
# and the interior doesn't contain that color (but can contain 6 or 9 or both)

def get_minimal_hollow_frames(grid):
    """Find minimal set of hollow frames (not nested)"""
    frames = []
    colors = sorted(set(c for row in grid for c in row))

    for color in colors:
        # Find all bboxes for this color
        bboxes = set()
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if grid[i][j] == color:
                    # Get bbox
                    min_r = max_r = i
                    min_c = max_c = j
                    for ni in range(i, len(grid)):
                        if grid[ni][j] == color:
                            max_r = max(max_r, ni)
                    for nj in range(j, len(grid[0])):
                        if grid[i][nj] == color:
                            max_c = max(max_c, nj)
                    for ni in range(i, max_r+1):
                        if grid[ni][min_c] == color:
                            min_r = min(min_r, ni)
                            max_r = max(max_r, ni)
                        if grid[ni][max_c] == color:
                            max_c = max(max_c, nj)
                    bboxes.add((min_r, min_c, max_r, max_c))

        # Check each bbox
        for tr, tc, br, bc in bboxes:
            height = br - tr + 1
            width = bc - tc + 1
            if height < 3 or width < 3:
                continue

            # Check border
            border_ok = True
            for h in range(height):
                if grid[tr+h][tc] != color or grid[tr+h][bc] != color:
                    border_ok = False
                for w in range(tc+1, bc):
                    if grid[tr][tc+w] != color or grid[br][tc+w] != color:
                        border_ok = False
            if not border_ok:
                continue

            # Interior
            interior = []
            for h in range(tr+1, br):
                for w in range(tc+1, bc):
                    interior.append((h, w, grid[h][w]))

            # Only include if interior is different from border color
            # and if interior is "empty" (mostly 6 or 9, not the same color)
            non_target_interior = [v for (r,c), v in interior if v != color]
            if non_target_interior:
                frames.append((color, tr, tc, br, bc, interior))

    return frames

