def find_hollow_frames_and_fill(grid):
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]

    frames = []
    for color in [0, 3, 5, 8, 9]:  # Non-background colors
        for i in range(h):
            for j in range(w):
                if grid[i][j] == color and not visited[i][j]:
                    # Try to find hollow frame of this color
                    # Find bounding box
                    min_r, max_r, min_c, max_c = i, i, j, j
                    for r in range(i, h):
                        for c in range(j, w):
                            if grid[r][c] == color:
                                min_r = min(min_r, r)
                                max_r = max(max_r, r)
                                min_c = min(min_c, c)
                                max_c = max(max_c, c)

                    # Check if this color forms a hollow rectangle
                    # Top row should be all color
                    top_ok = all(grid[min_r][c] == color for c in range(min_c, max_c+1))
                    bottom_ok = all(grid[max_r][c] == color for c in range(min_c, max_c+1))
                    left_ok = all(grid[r][min_c] == color for r in range(min_r, max_r+1))
                    right_ok = all(grid[r][max_c] == color for r in range(min_r, max_r+1))

                    if top_ok and bottom_ok and left_ok and right_ok:
                        # Check it's hollow (interior is not this color)
                        rt, rb, lc, rc = min_r, max_r, min_c, max_c
                        is_hollow = True
                        for r in range(rt+1, rb):
                            for c in range(lc+1, rc):
                                if grid[r][c] == color:
                                    is_hollow = False
                                    break
                            if not is_hollow:
                                break
                        if is_hollow:
                            # Collect all interior pixels
                            for r in range(rt+1, rb):
                                for c in range(lc+1, rc):
                                    visited[r][c] = True
                                    frames.append(((rt, rb, lc, rc), color, (r, c)))

    # Fill: even frames → 2, odd frames → 7 (same as before)
    color_to_fill = {0: 2, 8: 2, 3: 7, 5: 7, 9: 7}
    for frame, frame_color, (r, c) in frames:
        if output[r][c] != frame_color:  # Don't overwrite frame border
            output[r][c] = color_to_fill[frame_color]

    return output

