from collections import deque

def find_separate_hollow_frames(grid, start_r, start_c):
    """Find a hollow frame starting from an unvisited pixel of given color"""
    h, w = len(grid), len(grid[0])
    color = grid[start_r][start_c]

    # BFS to find all connected pixels of this color (one frame or multiple)
    frame_pixels = []
    queue = deque([(start_r, start_c)])
    visited_frame = [[False]*w for _ in range(h)]
    visited_frame[start_r][start_c] = True

    while queue:
        r, c = queue.popleft()
        frame_pixels.append((r, c))

        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < h and 0 <= nc < w:
                if not visited_frame[nr][nc] and grid[nr][nc] == color:
                    visited_frame[nr][nc] = True
                    queue.append((nr, nc))

    if len(frame_pixels) < 6:  # Minimum frame needs ~8 pixels
        return None

    # Find bounding box
    min_r, max_r = min(p[0] for p in frame_pixels), max(p[0] for p in frame_pixels)
    min_c, max_c = min(p[1] for p in frame_pixels), max(p[1] for p in frame_pixels)

    # Check if complete rectangle border
    top_ok = all(grid[min_r][c] == color for c in range(min_c, max_c+1))
    bottom_ok = all(grid[max_r][c] == color for c in range(min_c, max_c+1))
    left_ok = all(grid[r][min_c] == color for r in range(min_r, max_r+1))
    right_ok = all(grid[r][max_c] == color for r in range(min_r, max_r+1))

    if not (top_ok and bottom_ok and left_ok and right_ok):
        return None

    # Check hollow (interior not this color)
    is_hollow = True
    for r in range(min_r+1, max_r):
        for c in range(min_c+1, max_c):
            if grid[r][c] == color:
                is_hollow = False
                break
        if not is_hollow:
            break

    if not is_hollow:
        return None

    return (min_r, max_r, min_c, max_c, frame_pixels)

